CREATE OR REPLACE FUNCTION get_high_risk_cohort(p_condition_code VARCHAR(20), p_min_risk_score INTEGER)
RETURNS TABLE(patient_id INTEGER, full_name VARCHAR(100), condition_code VARCHAR(20), risk_score INTEGER, enrollment_date DATE)
AS $$
BEGIN
  RETURN QUERY (
    SELECT pc.patient_id, pc.full_name, pc.condition_code, pc.risk_score, pc.enrollment_date
    FROM patient_cohorts pc
    WHERE pc.condition_code = p_condition_code
      AND pc.risk_score >= p_min_risk_score
    ORDER BY pc.risk_score DESC, pc.patient_id ASC
  );
END;
$$ LANGUAGE plpgsql;

SELECT * FROM get_high_risk_cohort('DIAB', 70);
